112		out := make(chan reviewtypes.Event, 32)
113		go func() {
114			defer close(out)
115			out <- reviewtypes.Started{}
116			scanner := bufio.NewScanner(r)
117			scanner.Buffer(make([]byte, min(1024*1024, maxBuf)), maxBuf)
118			var seenTurnComplete, emittedTokens bool
119			var turnUsage codexUsage
