127					out <- reviewtypes.RunError{Err: fmt.Errorf("codex --json: %w", err)}
128					continue
129				}
130				// Add cases here when codex's envelope or item types grow; the
131				// default arm logs unknown types at Debug so drift can be
132				// triaged via ENTIRE_LOG_LEVEL=debug.
133				switch env.Type {
134				case "thread.started", "turn.started":
135					// Session/turn markers — no event emitted.
136				case "item.started":
137					if env.Item.Type == "command_execution" {
138						out <- reviewtypes.ToolCall{Name: "exec", Args: env.Item.Command}
139					}
140				case "item.completed":
141					if env.Item.Type == "agent_message" && env.Item.Text != "" {
142						out <- reviewtypes.AssistantText{Text: env.Item.Text}
143					}
144					// command_execution completion is intentionally swallowed —
145					// item.started already announced it. aggregated_output is the
146					// tool's stdout, not the model's narrative.
147					//
148					// No Tokens emission here: codex --json only carries usage on
149					// `turn.completed`. An earlier version of this parser also
150					// emitted Tokens here in case a future codex build attached
151					// a usage block, but that branch was unreachable against real
152					// codex output and is gone — emit on turn.completed only.
153				case "turn.completed":
154					seenTurnComplete = true
155					turnUsage = env.Usage
156					// Emit Tokens at every turn boundary so multi-turn reviews
157					// show iterative updates in the TUI. The post-loop emission
158					// is kept as a backstop for streams that ended without a
159					// turn.completed (defensive — shouldn't happen in practice).
160					if env.Usage.InputTokens > 0 || env.Usage.OutputTokens > 0 {
161						out <- reviewtypes.Tokens{
