177			if seenTurnComplete {
178				// Defensive backstop: the per-turn emission inside the
179				// `case "turn.completed"` arm above is the primary path and
180				// already emitted Tokens for every turn with non-zero usage.
181				// This fires only if no per-turn emission happened (e.g., a
