55	//
56	// Live-token semantics: Claude's assistant envelopes carry a usage snapshot
57	// taken at the START of each turn — input_tokens/cache_* are populated but
58	// output_tokens is essentially zero (a 1–8 token "initial decision" count
59	// that does not update as text streams). The true per-turn output is only
60	// surfaced on `result` (aggregate across all turns in the run) or on the
61	// late `message_delta` event of --include-partial-messages mode.
62	//
63	// We emit `Tokens{In: <sum>, Out: 0}` on each assistant envelope so the TUI
64	// can show context size growing across multi-turn runs, and `Tokens{In, Out}`
65	// on `result` with the final aggregate. Sending the misleading early
66	// "Out: 1" snapshot was removed after capturing real claude stream-json.
67	//
68	// Package-private; called directly from this package's tests so they can
69	// drive raw stdout fixtures through the parser without going through the
70	// ReviewerTemplate.Start spawn path.
71	func parseClaudeOutput(r io.Reader) <-chan reviewtypes.Event {
72		return parseClaudeOutputBuf(r, claudeReviewMaxScannerBuf)
73	}
74	
75	// claudeReviewMaxScannerBuf is the production bufio.Scanner cap for the Claude
76	// review parser. 64MB matches codex (which can pack large command stdout into
77	// aggregated_output); Claude's stream-json envelopes are small in practice but
78	// we share the cap so both parsers tolerate the same worst case. One buffer
79	// per active review run; memory cost is modest.
80	const claudeReviewMaxScannerBuf = 64 * 1024 * 1024
81	
82	// parseClaudeOutputBuf is the parameterized variant of parseClaudeOutput, used
83	// by tests to shrink the scanner cap so the "token too long" branch can be
84	// exercised without writing 64MB of fixture data.
85	func parseClaudeOutputBuf(r io.Reader, maxBuf int) <-chan reviewtypes.Event {
86		out := make(chan reviewtypes.Event, 32)
87		go func() {
88			defer close(out)
89			out <- reviewtypes.Started{}
90			scanner := bufio.NewScanner(r)
91			scanner.Buffer(make([]byte, min(1024*1024, maxBuf)), maxBuf)
92			var sawResult bool
93			var resultErr bool
94			var resultUsage messageUsage
95			for scanner.Scan() {
96				line := scanner.Bytes()
97				if len(line) == 0 {
98					continue
99				}
100				var env claudeEnvelope
101				if err := json.Unmarshal(line, &env); err != nil {
102					out <- reviewtypes.RunError{Err: fmt.Errorf("claude stream-json: %w", err)}
103					continue
104				}
105				switch env.Type {
106				case envelopeTypeAssistant:
107					for _, block := range env.Message.Content {
108						switch block.Type {
109						case "text":
110							if block.Text != "" {
111								out <- reviewtypes.AssistantText{Text: block.Text}
112							}
113						case "tool_use":
114							// block.Input is a json.RawMessage; passing it through as a
115							// string preserves the agent-defined shape without a
116							// re-marshal round trip. Empty input becomes "" so consumers
117							// see a falsy Args.
118							out <- reviewtypes.ToolCall{Name: block.Name, Args: string(block.Input)}
119						}
120					}
121					// The usage snapshot here is captured at the start of the
122					// turn, so output_tokens is essentially zero (1–8 tokens of
123					// initial decision, not the true output count). Surface input
124					// only — TUI consumers render input-only Tokens differently
125					// from finalized {In, Out} pairs. The final tally comes from
126					// the `result` envelope below.
127					if env.Message.Usage.InputTokens > 0 ||
128						env.Message.Usage.CacheReadInputTokens > 0 ||
129						env.Message.Usage.CacheCreationInputTokens > 0 {
130						in := env.Message.Usage.InputTokens +
131							env.Message.Usage.CacheReadInputTokens +
132							env.Message.Usage.CacheCreationInputTokens
133						out <- reviewtypes.Tokens{In: in, Out: 0}
134					}
135				case "result":
136					sawResult = true
137					resultErr = env.IsError
138					resultUsage = env.Usage
139				}
140			}
141			if err := scanner.Err(); err != nil {
142				out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
143				out <- reviewtypes.Finished{Success: false}
144				return
145			}
146			if sawResult {
147				in := resultUsage.InputTokens + resultUsage.CacheReadInputTokens + resultUsage.CacheCreationInputTokens
148				out <- reviewtypes.Tokens{In: in, Out: resultUsage.OutputTokens}
149				out <- reviewtypes.Finished{Success: !resultErr}
150				return
151			}
152			out <- reviewtypes.Finished{Success: false}
153		}()
154		return out
155	}
