// reviewerSkillSuffix annotates a reviewer with its configured skill count.
// Zero skills is rendered as "(no skills — generic review)" rather than
// "(0 skills)": for gemini/opencode that's the normal mode (they review
// without a skill system), and for claude/codex it tells the user the run
// will be a generic review they may want to refine via `entire review setup`.
func reviewerSkillSuffix(cfg settings.ReviewConfig) string {
	switch n := len(cfg.Skills); {
	case n == 1:
		return "(1 skill)"
	case n > 1:
		return fmt.Sprintf("(%d skills)", n)
	default:
		return "(no skills — generic review)"
	}
}

