package review

import "testing"

// TestFormatContextBanner pins the exact banner strings the user sees below
// the scope banner. The five branches mirror the five permutations:
// both/neither/checkpoints-only/sessions-only and the pluralisation seam.
func TestFormatContextBanner(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		in   ContextResult
		want string
	}{
		{
			name: "both nouns plural",
			in:   ContextResult{Checkpoints: 3, Sessions: 5},
			want: "Including 3 checkpoints and 5 sessions from this branch's history.",
		},
		{
			name: "both nouns singular",
			in:   ContextResult{Checkpoints: 1, Sessions: 1},
			want: "Including 1 checkpoint and 1 session from this branch's history.",
		},
		{
			name: "checkpoints only plural",
			in:   ContextResult{Checkpoints: 3, Sessions: 0},
			want: "Including 3 checkpoints from this branch's history.",
		},
		{
			name: "checkpoints only singular",
			in:   ContextResult{Checkpoints: 1, Sessions: 0},
			want: "Including 1 checkpoint from this branch's history.",
		},
		{
			name: "sessions only plural",
			in:   ContextResult{Checkpoints: 0, Sessions: 5},
			want: "Including 5 sessions from this branch's history.",
		},
		{
			name: "sessions only singular",
			in:   ContextResult{Checkpoints: 0, Sessions: 1},
			want: "Including 1 session from this branch's history.",
		},
		{
			name: "neither",
			in:   ContextResult{},
			want: "No prior session or checkpoint context for this branch yet.",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := formatContextBanner(tc.in); got != tc.want {
				t.Errorf("formatContextBanner(%+v) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}

func TestPluralizeContextNoun(t *testing.T) {
	t.Parallel()

	tests := []struct {
		n    int
		want string
	}{
		{n: 1, want: "1 checkpoint"},
		{n: 2, want: "2 checkpoints"},
		{n: 0, want: "0 checkpoints"},
	}
	for _, tc := range tests {
		if got := pluralizeContextNoun(tc.n, "checkpoint", "checkpoints"); got != tc.want {
			t.Errorf("pluralizeContextNoun(%d) = %q, want %q", tc.n, got, tc.want)
		}
	}
}

