if err != nil { return nil, fmt.Errorf("roles picker: %w", err) }

// Convert chosen roles into a ReviewConfig map for NormalizeRoles.
configMap := make(map[string]settings.ReviewConfig, len(chosen))
for name, role := range chosen {
    cfg := settings.ReviewConfig{Role: role}
    if saved != nil { // preserve existing Skills/Prompt across pickers
        if prev, ok := saved.Review[name]; ok {
            cfg.Skills = prev.Skills
            cfg.Prompt = prev.Prompt
        }
    }
    configMap[name] = cfg
}
normalized := NormalizeRoles(configMap)

pickSkills := forms.PickSkills
if pickSkills == nil { pickSkills = realPickSkills }
result := make(map[string]settings.ReviewConfig, len(normalized))
for _, name := range agentNames {
    cfg := normalized[name]
    if cfg.Role.IsReviewer() {
        prefill := settings.ReviewConfig{}
        if saved != nil { prefill = saved.Review[name] }
        prefill.Role = cfg.Role
        chosen, err := pickSkills(ctx, name, prefill)
        if err != nil { return nil, fmt.Errorf("skills picker for %s: %w", name, err) }
        chosen.Role = cfg.Role
        result[name] = chosen
    } else {
        // Fixer-only or Skip: no skills.
        result[name] = settings.ReviewConfig{Role: cfg.Role}
    }
}

// Persist via settings.Save (introduced in Chunk 1, Task 1.3 Step 5).
if saved == nil { saved = &settings.EntireSettings{} }
saved.Review = result
if err := settings.Save(ctx, saved); err != nil {
    return nil, fmt.Errorf("save settings: %w", err)
}

PrintSetupBanner(out, result)
return result, nil
